{
  "schemaVersion": "0.2",
  "slug": "radio-card",
  "name": "RadioCard",
  "status": "experimental",
  "purpose": "Presents radio options as selectable cards.",
  "scenarios": [
    "Choose a plan",
    "Choose a payment method",
    "Choose a theme option"
  ],
  "props": {
    "options": {
      "type": "string",
      "required": true,
      "description": "Array of option labels."
    },
    "value": {
      "type": "string",
      "required": false,
      "description": "Selected option.",
      "default": ""
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when selection changes."
    },
    "name": {
      "type": "string",
      "required": true,
      "description": "Radio group name."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "checked",
      "description": "One option is selected."
    },
    {
      "name": "unchecked",
      "description": "No option is selected."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "page",
      "dialog"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use when options are not mutually exclusive.",
    "Do not use without a label."
  ],
  "a11y": {
    "role": "radiogroup",
    "keyboard": [
      "Arrow keys move selection",
      "Space selects"
    ],
    "focus": "Radio inputs are focusable.",
    "labeling": "Name groups the radios; labels provide option names.",
    "wcag": [
      "3.3.2",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Grid or stack of cards.",
    "breakpoints": {
      "compact": "Single column.",
      "medium": "Two columns.",
      "large": "Three columns."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "radio-card",
    "states": [
      "checked",
      "unchecked"
    ],
    "intents": [
      "select-single",
      "compare-options"
    ]
  }
}

import { RadioGroupPrimitive } from '@chameleon-ui/primitives'
import './styles.css'

export interface RadioCardProps {
  options: string[]
  value?: string
  onChange: (value: string) => void
  name: string
  className?: string
}

export function RadioCard({ options, value = '', onChange, name, className }: RadioCardProps) {
  const classes = ['cu-radio-card', className].filter(Boolean).join(' ')
  return (
    <RadioGroupPrimitive.Root
      className={classes}
      data-ai-role="radio-card" data-ai-intent="select-single"
      data-ai-state={value ? 'checked' : 'unchecked'}
      name={name}
      value={value}
      onValueChange={(details) => onChange(details.value ?? '')}
    >
      {options.map((option) => (
        <RadioGroupPrimitive.Item className="cu-radio-card__item" key={option} value={option}>
          <RadioGroupPrimitive.ItemControl className="cu-radio-card__control" />
          <RadioGroupPrimitive.ItemText className="cu-radio-card__text">{option}</RadioGroupPrimitive.ItemText>
        </RadioGroupPrimitive.Item>
      ))}
    </RadioGroupPrimitive.Root>
  )
}

.cu-radio-card {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-radio-card__item {
  display: flex;
  align-items: center;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  cursor: pointer;
}

.cu-radio-card__item[data-state='checked'] {
  border-color: var(--cu-color-palette-brand);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-radio-card__control {
  inline-size: 1.25rem;
  block-size: 1.25rem;
  border: 2px solid var(--cu-color-border-default);
  border-radius: 50%;
}

.cu-radio-card__item[data-state='checked'] .cu-radio-card__control {
  border-color: var(--cu-color-palette-brand);
  background: radial-gradient(circle, var(--cu-color-palette-brand) 50%, transparent 55%);
}

.cu-radio-card__item:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}
